#!/usr/bin/env bash
# Starts Znuny + MariaDB, installs the database, creates an API agent, a customer user and two
# dynamic fields, and imports the stock GenericTicketConnectorREST web services plus a web
# service with operation-name routes and a webhook requester generated by the package.
set -euo pipefail

cd "$(dirname "$0")"

export ZNUNY_IMAGE="${ZNUNY_IMAGE:-cygnusnetworks/znuny:7.3.8}"
export ZNUNY_PLATFORM="${ZNUNY_PLATFORM:-linux/amd64}"

# Git ref for files that are not part of the image: rel-X_Y_Z for an X.Y.Z image tag.
tag="${ZNUNY_IMAGE##*:}"
if [[ "$tag" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then default_ref="rel-${tag//./_}"; else default_ref="rel-7_3_8"; fi
ZNUNY_GIT_REF="${ZNUNY_GIT_REF:-$default_ref}"
compose() { docker compose -p laravel-znuny-integration "$@"; }

compose up -d db

echo "Waiting for MariaDB..."
until compose exec -T db healthcheck.sh --connect --innodb_initialized >/dev/null 2>&1; do
  sleep 2
done

if ! compose exec -T db mariadb -uznuny -pznuny znuny -e 'SELECT 1 FROM valid LIMIT 1' >/dev/null 2>&1; then
  echo "Installing the Znuny database..."
  for file in schema.mysql.sql initial_insert.mysql.sql schema-post.mysql.sql; do
    docker run --rm --platform "$ZNUNY_PLATFORM" --entrypoint cat "$ZNUNY_IMAGE" "/opt/otrs/scripts/database/$file" \
      | compose exec -T db mariadb -uznuny -pznuny znuny
  done
fi

compose create znuny
compose cp ./Config.pm znuny:/opt/otrs/Kernel/Config.pm
compose start znuny

echo "Waiting for Znuny..."
for attempt in $(seq 1 200); do
  curl -fsS http://localhost:8080/otrs/index.pl >/dev/null 2>&1 && break
  if [ "$(docker inspect -f '{{.State.Running}}' "$(compose ps -aq znuny)")" != "true" ]; then
    echo "The Znuny container stopped:" >&2
    compose logs --tail 30 znuny >&2
    exit 1
  fi
  sleep 3
done
curl -fsS http://localhost:8080/otrs/index.pl >/dev/null || { echo "Znuny did not answer in time." >&2; exit 1; }

console() { compose exec -T -u otrs znuny /opt/otrs/bin/otrs.Console.pl "$@"; }

# Znuny keeps UTC unless ZNUNY_OTRS_TIMEZONE names another OTRSTimeZone, e.g. Europe/Berlin.
if [ -n "${ZNUNY_OTRS_TIMEZONE:-}" ]; then
  console Admin::Config::Update --setting-name OTRSTimeZone --value "$ZNUNY_OTRS_TIMEZONE"
fi

console Admin::User::Add --user-name api-agent --first-name API --last-name Agent \
  --email-address api-agent@example.com --password api-secret || true
console Admin::Group::UserLink --user-name api-agent --group-name users --permission rw || true
console Admin::CustomerUser::Add --user-name jane --first-name Jane --last-name Doe \
  --email-address jane@example.com --customer-id acme --password jane-secret || true
# Downloads a file from the Znuny repository and copies it into the container.
fetch() {
  local file
  file=$(mktemp)
  curl -fsSL "https://raw.githubusercontent.com/znuny/Znuny/$1" -o "$file"
  chmod 644 "$file"
  compose cp "$file" "znuny:$2"
  rm -f "$file"
}

# Znuny ships the example web service since 6.5.11 and 7.1.3. Older versions have the
# operations it uses, so they get the file of a newer release.
example=/opt/otrs/var/webservices/examples/GenericTicketConnectorREST.yml
if ! compose exec -T znuny test -f "$example"; then
  example=/tmp/GenericTicketConnectorREST.yml
  fetch "rel-7_3_8/var/webservices/examples/GenericTicketConnectorREST.yml" "$example"
fi
console Admin::WebService::Add --name GenericTicketConnectorREST --source-path "$example" || true

# The classic example (development/webservices) is not part of the release; fetch it from GitHub.
fetch "${ZNUNY_GIT_REF}/development/webservices/GenericTicketConnectorREST.yml" /tmp/GenericTicketConnectorRESTClassic.yml
console Admin::WebService::Add --name GenericTicketConnectorRESTClassic \
  --source-path /tmp/GenericTicketConnectorRESTClassic.yml || true

# These two web services come from the package's own generator (php artisan znuny:webservice),
# so the suite also proves that generated files import and work on this Znuny version.
(cd ../../.. && vendor/bin/testbench package:discover >/dev/null)
import_generated() {
  local name=$1 file
  shift
  file=$(mktemp)
  (cd ../../.. && vendor/bin/testbench znuny:webservice "$@" --output="$file" >/dev/null)
  chmod 644 "$file"
  compose cp "$file" "znuny:/tmp/$name.yml"
  rm -f "$file"
  console Admin::WebService::Add --name "$name" --source-path "/tmp/$name.yml" || true
}

import_generated OperationNameREST --routes=operation-name
ZNUNY_WEBHOOK_TOKEN=integration-token import_generated LaravelWebhook --routes=operation-name \
  --webhooks=TicketCreate --webhook-url=http://host.docker.internal:8099 --with-token --sync

compose cp ./dynamic-fields.yml znuny:/tmp/dynamic-fields.yml
console Admin::DynamicField::Import /tmp/dynamic-fields.yml

echo "Checking the API login..."
curl -fsS -X POST -H 'Content-Type: application/json' \
  -d '{"UserLogin":"api-agent","Password":"api-secret"}' \
  http://localhost:8080/otrs/nph-genericinterface.pl/Webservice/GenericTicketConnectorREST/Session \
  | grep -q SessionID || { echo "The API agent cannot log in; see the output above." >&2; exit 1; }

# The zone Znuny really uses: a re-run without ZNUNY_OTRS_TIMEZONE keeps an earlier setting.
timezone=$(console Admin::Config::Read --setting-name OTRSTimeZone | awk '/^Setting: OTRSTimeZone/ { getline; print; exit }')

cat <<TEXT

Znuny is ready:

  ZNUNY_INTEGRATION_URL=http://localhost:8080/otrs/nph-genericinterface.pl/Webservice/GenericTicketConnectorREST
  ZNUNY_INTEGRATION_CLASSIC_URL=http://localhost:8080/otrs/nph-genericinterface.pl/Webservice/GenericTicketConnectorRESTClassic
  ZNUNY_INTEGRATION_OPERATION_NAME_URL=http://localhost:8080/otrs/nph-genericinterface.pl/Webservice/OperationNameREST
  ZNUNY_INTEGRATION_USERNAME=api-agent
  ZNUNY_INTEGRATION_PASSWORD=api-secret
  ZNUNY_INTEGRATION_CUSTOMER_USER=jane
  ZNUNY_INTEGRATION_CUSTOMER_PASSWORD=jane-secret
  ZNUNY_INTEGRATION_WEBHOOK_LISTEN=0.0.0.0:8099
  ZNUNY_INTEGRATION_TIMEZONE=${timezone:-UTC}

TEXT
